function normalizeUsers(list) {
  return list.map(({ id, first_name, last_name, email, profile }) => ({
    id,
    fullName: `${first_name} ${last_name}`,
    email: email.trim().toLowerCase(),
    age: profile?.age ?? null,
    city: profile?.city ?? 'не указан',
  }));
}
